@requests = Thread::Queue.new
@worker = Thread.new do
  while (req = @requests.pop)                   # scheduler: one at a time
    req[:reply] << @servant.put_i(req[:msg])    # publish the result
  end
end

def put(msg)                                    # proxy
  reply = Thread::Queue.new                     # future-ish reply handle
  @requests << { msg: msg, reply: reply }
  reply
end
